def sort(a):
    """原地 TimSort。"""
    n = len(a)
    if n < 2:
        return

    MIN_RUN = 32

    # ---------- 插入排序：对 a[lo:hi] 升序排序 ----------
    def insertion_sort(lo, hi):
        for i in range(lo + 1, hi):
            key = a[i]
            j = i - 1
            while j >= lo and a[j] > key:
                a[j + 1] = a[j]
                j -= 1
            a[j + 1] = key

    # ---------- 归并：把 a[lo:mid] 和 a[mid:hi] 合并 ----------
    def merge(lo, mid, hi):
        left = a[lo:mid]
        right = a[mid:hi]
        i = j = 0
        k = lo
        while i < len(left) and j < len(right):
            # <= 保证稳定性
            if left[i] <= right[j]:
                a[k] = left[i]
                i += 1
            else:
                a[k] = right[j]
                j += 1
            k += 1
        while i < len(left):
            a[k] = left[i]
            i += 1
            k += 1
        while j < len(right):
            a[k] = right[j]
            j += 1
            k += 1

    # ---------- 计算最小 run 长度 ----------
    # 取 32~64 之间，使 n/min_run 接近 2 的幂，便于归并
    def min_run_length(n):
        r = 0
        while n >= MIN_RUN:
            r |= n & 1
            n >>= 1
        return n + r

    min_run = min_run_length(n)

    # ---------- 第一步：扫描自然 run，补足并排序 ----------
    i = 0
    while i < n:
        # 找一段自然有序（升序或严格降序）
        run_hi = i + 1
        if run_hi < n:
            if a[run_hi] < a[i]:
                # 严格降序：一路找下去，然后反转
                while run_hi < n and a[run_hi] < a[run_hi - 1]:
                    run_hi += 1
                a[i:run_hi] = reversed(a[i:run_hi])
            else:
                # 非降序
                while run_hi < n and a[run_hi] >= a[run_hi - 1]:
                    run_hi += 1

        # 如果 run 太短，用插入排序扩展到 min_run
        if run_hi - i < min_run:
            run_hi = min(i + min_run, n)
            insertion_sort(i, run_hi)

        i = run_hi

    # ---------- 第二步：自底向上归并所有 run ----------
    size = min_run
    while size < n:
        for lo in range(0, n, 2 * size):
            mid = min(lo + size, n)
            hi = min(lo + 2 * size, n)
            if mid < hi:
                merge(lo, mid, hi)
        size *= 2

