import math


def sort(a):
    n = len(a)
    if n <= 1:
        return

    max_depth = 2 * int(math.log2(n))

    def insertion_sort(lo, hi):
        for i in range(lo + 1, hi + 1):
            key = a[i]
            j = i - 1
            while j >= lo and a[j] > key:
                a[j + 1] = a[j]
                j -= 1
            a[j + 1] = key

    def sift_down(i, lo, hi):
        while True:
            largest = i
            left = 2 * i + 1
            right = 2 * i + 2
            if left <= hi and a[left] > a[largest]:
                largest = left
            if right <= hi and a[right] > a[largest]:
                largest = right
            if largest == i:
                break
            a[i], a[largest] = a[largest], a[i]
            i = largest

    def heap_sort(lo, hi):
        size = hi - lo + 1
        for i in range(lo + size // 2 - 1, lo - 1, -1):
            sift_down(i, lo, hi)
        for end in range(hi, lo, -1):
            a[lo], a[end] = a[end], a[lo]
            sift_down(lo, lo, end - 1)

    def partition(lo, hi):
        mid = (lo + hi) // 2
        # 三数取中
        if a[mid] < a[lo]:
            a[mid], a[lo] = a[lo], a[mid]
        if a[hi] < a[lo]:
            a[hi], a[lo] = a[lo], a[hi]
        if a[hi] < a[mid]:
            a[hi], a[mid] = a[mid], a[hi]
        pivot = a[mid]
        a[mid], a[hi - 1] = a[hi - 1], a[mid]
        i = lo
        j = hi - 1
        while True:
            i += 1
            while a[i] < pivot:
                i += 1
            j -= 1
            while a[j] > pivot:
                j -= 1
            if i >= j:
                break
            a[i], a[j] = a[j], a[i]
        a[i], a[hi - 1] = a[hi - 1], a[i]
        return i

    def intro_sort(lo, hi, depth):
        while hi - lo > 16:
            if depth == 0:
                heap_sort(lo, hi)
                return
            depth -= 1
            p = partition(lo, hi)
            intro_sort(p + 1, hi, depth)
            hi = p - 1
        insertion_sort(lo, hi)

    intro_sort(0, n - 1, max_depth)

