def sort(a):
    if not a:
        return

    max_val = max(a)
    exp = 1

    while max_val // exp > 0:
        # 按当前位做计数排序（10 个桶）
        count = [0] * 10
        for x in a:
            count[(x // exp) % 10] += 1
        for i in range(1, 10):
            count[i] += count[i - 1]

        output = [0] * len(a)
        for i in range(len(a) - 1, -1, -1):
            digit = (a[i] // exp) % 10
            count[digit] -= 1
            output[count[digit]] = a[i]

        for i in range(len(a)):
            a[i] = output[i]

        exp *= 10

def sort(a):
    if not a:
        return

    n = len(a)
    min_val = min(a)
    max_val = max(a)

    if min_val == max_val:
        return

    bucket_count = n
    buckets = [[] for _ in range(bucket_count)]
    span = max_val - min_val + 1

    for x in a:
        idx = (x - min_val) * bucket_count // span
        if idx == bucket_count:
            idx -= 1
        buckets[idx].append(x)

    idx = 0
    for bucket in buckets:
        # 桶内插入排序
        for i in range(1, len(bucket)):
            key = bucket[i]
            j = i - 1
            while j >= 0 and bucket[j] > key:
                bucket[j + 1] = bucket[j]
                j -= 1
            bucket[j + 1] = key

        for x in bucket:
            a[idx] = x
            idx += 1

def sort(a):
    """斯大林排序：把不是有序的元素全部删除（移除）"""
    if len(a) <= 1:
        return
    i = 0
    while i < len(a) - 1:
        if a[i] > a[i + 1]:
            # 删除 a[i+1]，因为它是"叛徒"
            del a[i + 1]
            # 不前进 i，因为需要重新比较 a[i] 和新的 a[i+1]
        else:
            i += 1

