def sort(a):
    """猴子排序 (Bogosort) —— 完整打乱版，手写 shuffle 以便可视化钩子捕获"""
    import random
    n = len(a)
    if n < 2:
        return

    def is_sorted():
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                return False
        return True

    def shuffle():
        # 手写 Fisher-Yates，保证均匀打乱，且每次交换都经过 __setitem__
        for i in range(n - 1, 0, -1):
            j = random.randrange(i + 1)   # [0, i]，开区间上界 i+1
            a[i], a[j] = a[j], a[i]

    while not is_sorted():
        shuffle()
